(function(){'use strict';
const demoHandler=$('eventDemo').onclick,card=$('calcRetention').closest('article');card.innerHTML=`<div class="cardhead"><h2>Retention explorer</h2><span class="tag">R1 → R180</span></div><p>Chọn cohort từ ngày X đến Y, các ngày retention cần xem và event được tính là quay lại.</p><div class="toolbar"><button id="eventDemo">Dùng event log mẫu</button><button id="retQuery">Nhận event log BigQuery</button><button id="retUseImport">Dùng file đã import</button><button id="retExport">↓ Xuất retention CSV</button></div><div class="formgrid"><label>Event tạo cohort<input id="cohortEvent" value="first_open"></label><label>Event phân nhóm ở D0 (để trống = toàn bộ)<input id="eventName" value="tutorial_complete"></label><label>Cohort từ ngày X<input id="retFrom" type="date"></label><label>Cohort đến ngày Y<input id="retTo" type="date"></label><label>Dữ liệu đầy đủ đến hết ngày<input id="retUntil" type="date"></label><label>Event quay lại<input id="retActive" value="*" placeholder="* = mọi event"></label><label>Platform<select id="retPlatform"><option value="">Tất cả</option></select></label><label>Quốc gia<select id="retCountry"><option value="">Tất cả</option></select></label><label>Ngày retention bắt đầu R<input id="retStart" type="number" min="1" max="180" value="1"></label><label>Ngày retention kết thúc R<input id="retEnd" type="number" min="1" max="180" value="30"></label></div><div class="toolbar ret-presets">${[1,3,7,14,30,60,90,180].map(n=>'<label><input type="checkbox" data-ret-day="'+n+'" '+(n<=30?'checked':'')+'> R'+n+'</label>').join('')}<label><input id="retAllDays" type="checkbox" checked> Tất cả ngày trong khoảng R</label></div><div class="toolbar"><button id="calcRetention" class="primary">Vẽ chart retention</button><span id="retStatus" role="status"></span></div><p class="muted">R1 = quay lại đúng ngày lịch sau ngày tạo cohort (UTC). Mỗi Rx chỉ tính user đã đủ ngày quan sát. Không phát sinh event = không quay lại; cohort chưa đủ ngày hiển thị “—”.</p><div id="retention"></div><div id="retCharts" hidden><div class="cardhead"><h2>Đường retention theo ngày R</h2><select id="retGroup" aria-label="Nhóm retention"><option value="all">Toàn bộ user</option><option value="both">Có / không có event D0</option><option value="yes">Có event D0</option><option value="no">Không có event D0</option></select></div><p id="retCurveCaption" class="muted"></p><div id="retCurve"></div><div class="cardhead ab-trend-title"><h2>Retention từ ngày X đến Y</h2><label>R đang xem<select id="retDay" aria-label="R đang xem"></select></label></div><p class="muted">Trục X = ngày tạo cohort; trục Y = retention của R đã chọn. Mỗi điểm có mẫu số đủ thời gian riêng.</p><div id="retCalendar"></div><div class="cardhead ab-trend-title"><h2>Ma trận cohort × ngày retention</h2></div><div id="retHeatmap" class="tablewrap"></div></div><p class="muted">Phân nhóm theo event ở D0 là tương quan. Lấy đủ lịch sử first_open và event đến ngày quan sát; filter phân khúc dùng thuộc tính lúc tạo cohort.</p>`;
let data=null,dataRef=null,report=null,inputOverride=null;
function clear(){report=null;$('retCharts').hidden=true;$('retention').innerHTML='';$('retStatus').textContent='Bộ lọc thay đổi — bấm Vẽ chart để cập nhật.'}
function normalizeData(input){if(input===inputOverride)return AB.normalize(input);const map={};for(const [key,role]of Object.entries(mapping)){if(role==='user_id')map.user=key;if(role==='event_name')map.event=key;if(role==='event_date'||role==='date')map.time=key}return AB.normalize(input,map)}
function sync(input=inputOverride||rows){if(dataRef===input&&data)return;data=null;report=null;$('retCharts').hidden=true;data=normalizeData(input);dataRef=input;const dates=data.events.filter(e=>e.event===$('cohortEvent').value).map(e=>e.date).sort(),all=data.events.map(e=>e.date).sort();$('retFrom').value=dates[0]||all[0];$('retTo').value=dates.at(-1)||all.at(-1);$('retUntil').value=all.at(-1);for(const [id,key]of [['retCountry','country'],['retPlatform','platform']])$(id).innerHTML='<option value="">Tất cả</option>'+[...new Set(data.events.map(e=>e.dims[key]).filter(Boolean))].sort().map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('')}
function getConfig(){const a=Number($('retStart').value),b=Number($('retEnd').value);if(!Number.isInteger(a)||!Number.isInteger(b)||a<1||b>180||a>b)throw Error('Khoảng ngày retention phải là R1–R180, bắt đầu ≤ kết thúc.');const days=$('retAllDays').checked?Array.from({length:b-a+1},(_,i)=>i+a):[...card.querySelectorAll('[data-ret-day]:checked')].map(e=>Number(e.dataset.retDay)).filter(n=>n>=a&&n<=b).sort((a,b)=>a-b);return {from:$('retFrom').value,to:$('retTo').value,until:$('retUntil').value,days,cohortEvent:$('cohortEvent').value.trim(),segmentEvent:$('eventName').value.trim(),activeEvent:$('retActive').value.trim()||'*',platform:$('retPlatform').value,country:$('retCountry').value}}
function groupName(group){return group==='all'?'Toàn bộ user':(group==='yes'?'Có ':'Không có ')+$('eventName').value+' ở D0'}
function selectedGroups(){return $('retGroup').value==='both'?['yes','no']:[$('retGroup').value]}
function draw(){if(!report)return;const groups=selectedGroups().filter(g=>report.overall.some(x=>x.group===g)),r=Number($('retDay').value);$('retCurveCaption').textContent='Cohort '+report.from+' → '+report.to+' · Quan sát đến '+report.until+' · '+report.users+' user';$('retCurve').innerHTML=MetricCharts.chart(report.overall.filter(g=>groups.includes(g.group)).map(g=>({name:groupName(g.group),points:g.points.map(p=>({x:p.day,y:p.rate,n:p.eligible}))})),{percent:true,dayAxis:true,label:'Đường retention R'+report.overall[0].points[0].day+' đến R'+report.overall[0].points.at(-1).day});$('retCalendar').innerHTML=MetricCharts.chart(groups.map(group=>({name:groupName(group)+' · R'+r,points:report.byCohort.map(c=>{const p=c.groups.find(g=>g.group===group).points.find(p=>p.day===r);return {x:c.date,y:p.rate,n:p.eligible}})})),{percent:true,label:'Retention R'+r+' từ '+report.from+' đến '+report.to});const days=report.overall[0].points.map(p=>p.day);$('retHeatmap').innerHTML='<table><thead><tr><th>Cohort</th><th>Nhóm</th>'+days.map(n=>'<th>R'+n+'</th>').join('')+'</tr></thead><tbody>'+report.byCohort.flatMap(c=>c.groups.filter(g=>groups.includes(g.group)).map(g=>'<tr><td>'+c.date+'</td><td>'+esc(groupName(g.group))+'</td>'+g.points.map(p=>'<td title="'+p.retained+' / '+p.eligible+' user đủ ngày" style="background:'+(p.rate===null?'#f5f6f8':'rgba(20,138,112,'+(p.rate/100*.5+.04)+')')+'">'+(p.rate===null?'—':p.rate.toFixed(1)+'%')+'</td>').join('')+'</tr>')).join('')+'</tbody></table>'}
$('calcRetention').onclick=()=>{try{sync();const c=getConfig();report=Retention.analyze(data.events,c);const previous=$('retDay').value;$('retDay').innerHTML=c.days.map(n=>'<option value="'+n+'">R'+n+'</option>').join('');if(c.days.includes(Number(previous)))$('retDay').value=previous;$('retGroup').querySelectorAll('option').forEach(o=>o.disabled=!c.segmentEvent&&o.value!=='all');if(!c.segmentEvent)$('retGroup').value='all';$('retCharts').hidden=false;$('retention').innerHTML='<p><b>'+report.users+' user cohort</b> · '+data.issues.invalid+' dòng event lỗi bị bỏ qua</p>';$('retStatus').textContent='Đã cập nhật '+c.days.length+' ngày retention.';draw()}catch(e){clear();$('retStatus').textContent=e.message}};
$('eventDemo').onclick=()=>{inputOverride=null;demoHandler()};$('retUseImport').onclick=()=>{try{inputOverride=null;dataRef=null;sync();$('calcRetention').click()}catch(e){$('retStatus').textContent=e.message}};$('retQuery').onclick=()=>{try{if(!queryRows.length)throw Error('Chạy query trả về event log trước.');if($('queryStatus').textContent.includes('KẾT QUẢ BỊ GIỚI HẠN'))throw Error('Query bị cắt bớt. Thu hẹp scope trước khi phân tích retention.');AB.normalize(queryRows);inputOverride=queryRows;dataRef=null;data=null;sync();$('calcRetention').click()}catch(e){$('retStatus').textContent=e.message}};
card.querySelectorAll('[data-ret-day]').forEach(e=>e.onchange=()=>{$('retAllDays').checked=false;const selected=[...card.querySelectorAll('[data-ret-day]:checked')].map(e=>+e.dataset.retDay);if(selected.length){$('retStart').value=Math.min(...selected);$('retEnd').value=Math.max(...selected)}clear()});['retFrom','retTo','retUntil','retStart','retEnd','retAllDays','retCountry','retPlatform','retActive','eventName','cohortEvent'].forEach(id=>$(id).addEventListener('change',clear));$('retGroup').onchange=draw;$('retDay').onchange=draw;
document.querySelector('[data-tab="product"]').addEventListener('click',()=>{try{sync()}catch(e){$('retStatus').textContent='Nhập event log hoặc dùng dữ liệu mẫu.'}});
const pageObserver=new MutationObserver(()=>{if(!$('product').hidden){try{sync()}catch(e){$('retStatus').textContent='Nhập event log hoặc dùng dữ liệu mẫu.'}}});pageObserver.observe($('product'),{attributes:true,attributeFilter:['hidden']});
$('retExport').onclick=()=>{if(!report){$('retStatus').textContent='Vẽ chart trước khi xuất.';return}const result=report.overall.flatMap(g=>g.points.map(p=>[groupName(g.group),p.day,p.eligible,p.retained,p.rate??'']));download('retention.csv','group,day,eligible_users,retained_users,retention_pct\n'+result.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv')};
})();

